"""Validation API for request batches."""

import math


def evaluate(request, policy):
    """Validate request rows against policy without modifying either input."""
    accepted = []
    errors = []
    seen = set()

    for index, row in enumerate(request.get("rows", [])):
        row_id = row.get("id")
        amount = row.get("amount")
        unit = row.get("unit", policy["base_unit"])

        if not isinstance(row_id, str) or not row_id:
            cause = "id"
        elif (
            isinstance(amount, bool)
            or not isinstance(amount, (int, float))
            or not math.isfinite(amount)
            or amount < 0
        ):
            cause = "amount"
        elif unit not in policy["units"]:
            cause = "unit"
        elif policy.get("unique", False) and row_id in seen:
            cause = "duplicate"
        else:
            cause = None

        if cause is not None:
            errors.append({"row": index, "cause": cause})
            continue

        seen.add(row_id)
        accepted.append({
            "id": row_id,
            "amount": amount * policy["units"][unit],
        })

    if errors:
        return {"ok": False, "records": [], "errors": errors}
    return {"ok": True, "records": accepted, "errors": []}

