import copy, json, math; from work import evaluate

def check(req, pol, exp):
 r0=copy.deepcopy(req); p0=copy.deepcopy(pol); got=evaluate(req,pol); assert got==exp,(got,exp); assert req==r0 and pol==p0
p={'base_unit':'nm','units':{'nm':1,'um':1000},'unique':True}
check({'rows':[{'id':'a','amount':2},{'id':'a','amount':3,'unit':'um'}]},p,{'ok':False,'records':[],'errors':[{'row':1,'cause':'duplicate'}]})
check({'rows':[{'id':'','amount':-1,'unit':'bad'},{'id':'x','amount':True,'unit':'bad'},{'id':'x','amount':1,'unit':'bad'},{'id':'x','amount':2},{'id':'x','amount':3}]},p,{'ok':False,'records':[],'errors':[{'row':0,'cause':'id'},{'row':1,'cause':'amount'},{'row':2,'cause':'unit'},{'row':4,'cause':'duplicate'}]})
check({'rows':[{'id':'z','amount':0,'unit':'um'}]},p,{'ok':True,'records':[{'id':'z','amount':0}],'errors':[]})
for bad in [float('nan'),float('inf'),float('-inf'),-0.1,True,'1',None]:
 got=evaluate({'rows':[{'id':'q','amount':bad}]},p); assert got=={'ok':False,'records':[],'errors':[{'row':0,'cause':'amount'}]},(bad,got)
print(json.dumps({'boundary_checks':'passed'}))

