import copy, json
from work import evaluate

def verify(req, pol, expected):
    req_before = copy.deepcopy(req)
    pol_before = copy.deepcopy(pol)
    actual = evaluate(req, pol)
    assert actual == expected, (actual, expected)
    assert req == req_before and pol == pol_before
    assert set(actual) == {'ok','records','errors'}
    for record in actual['records']:
        assert set(record) == {'id','amount'}
    for error in actual['errors']:
        assert set(error) == {'row','cause'}

p = {'base_unit':'m','units':{'m':1,'cm':0.01},'unique':True}
verify({'rows':[{'id':'a','amount':2,'unit':'cm'},{'id':'b','amount':3}]}, p, {'ok':True,'records':[{'id':'a','amount':0.02},{'id':'b','amount':3}],'errors':[]})
verify({'rows':[{'id':'x','amount':-1,'unit':'bad'},{'id':'x','amount':1,'unit':'bad'},{'id':'x','amount':2},{'id':'x','amount':3},{'id':False,'amount':0}]}, p, {'ok':False,'records':[],'errors':[{'row':0,'cause':'amount'},{'row':1,'cause':'unit'},{'row':3,'cause':'duplicate'},{'row':4,'cause':'id'}]})
verify({'rows':[{'id':'q','amount':1,'unit':'bad'},{'id':'q','amount':2}]}, p, {'ok':False,'records':[],'errors':[{'row':0,'cause':'unit'}]})
for bad in (True, False, float('nan'), float('inf'), float('-inf'), -0.01, '1', None):
    verify({'rows':[{'id':'n','amount':bad}]}, p, {'ok':False,'records':[],'errors':[{'row':0,'cause':'amount'}]})
verify({'rows':[{'id':'same','amount':1},{'id':'same','amount':2}]}, {'base_unit':'m','units':{'m':1},'unique':False}, {'ok':True,'records':[{'id':'same','amount':1},{'id':'same','amount':2}],'errors':[]})
print(json.dumps({'independent_boundary_checks':'passed'}))

